import { env } from "zttp:env";
import { parallel } from "zttp:io";

export function handler(req: Request): Proof<Response, "no_secret_leakage" | "state_isolated"> {
  const secretReads = parallel([(): boolean => env("API_SECRET") === undefined]);
  const apiSecretMissing: boolean = secretReads[0];
  if (apiSecretMissing) {
    return Response.json({ error: "service unavailable" }, { status: 503 });
  }
  const nameReads = parallel([(): string | undefined => env("APP_NAME")]);
  const appName: string = nameReads[0] ?? "unnamed";
  return Response.json({ appName: appName });
}
```
